const { diffLines, unifiedHunks, applyHunks } = require('./src/diff');

function lcsLength(a, b) {
  const row = new Array(b.length + 1).fill(0);
  for (const line of a) {
    let diagonal = 0;
    for (let j = 1; j <= b.length; j++) {
      const previous = row[j];
      row[j] = line === b[j - 1] ? diagonal + 1 : Math.max(row[j], row[j - 1]);
      diagonal = previous;
    }
  }
  return row[b.length];
}

function expectedHunks(script, context) {
  const ranges = [];
  for (let i = 0; i < script.length; i++) {
    if (script[i].op === 'equal') continue;
    const start = Math.max(0, i - context);
    const end = Math.min(script.length, i + context + 1);
    const last = ranges[ranges.length - 1];
    if (last && start <= last[1]) last[1] = end;
    else ranges.push([start, end]);
  }
  return ranges.map(([start, end]) => {
    const oldBefore = script.slice(0, start).filter(e => e.op !== 'insert').length;
    const newBefore = script.slice(0, start).filter(e => e.op !== 'delete').length;
    const entries = script.slice(start, end);
    const oldLines = entries.filter(e => e.op !== 'insert').length;
    const newLines = entries.filter(e => e.op !== 'delete').length;
    return {
      oldStart: oldBefore + (oldLines ? 1 : 0), oldLines,
      newStart: newBefore + (newLines ? 1 : 0), newLines,
      lines: entries.map(e => ({ equal: ' ', delete: '-', insert: '+' })[e.op] + e.line),
    };
  });
}

const alphabet = ['', 'x', '+'];
const arrays = [[]];
